import { useState } from 'react';
import './App.css';
import SingleCheck from './components/SingleCheck';
import BulkVerify from './components/BulkVerify';

const TABS = [
  { id: 'single', label: 'Single check' },
  { id: 'bulk', label: 'Bulk verify' },
];

export default function App() {
  const [tab, setTab] = useState('single');

  return (
    <div style={{ minHeight: '100vh', background: 'var(--bg)' }}>
      <div style={{ maxWidth: 760, margin: '0 auto', padding: '0 24px 80px' }}>

        {/* Header */}
        <div style={{ padding: '40px 0 32px', borderBottom: '1px solid var(--border)', marginBottom: 36 }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 14, marginBottom: 8 }}>
            <div style={{
              width: 38, height: 38,
              background: 'var(--accent)',
              borderRadius: 10,
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              fontSize: 18,
            }}>✉</div>
            <h1 style={{ fontFamily: 'Syne', fontSize: 22, fontWeight: 700, color: 'var(--text)', letterSpacing: '-0.02em' }}>
              MailClean
            </h1>
            <span style={{
              background: 'var(--bg3)',
              border: '1px solid var(--border)',
              borderRadius: 6,
              padding: '2px 8px',
              fontSize: 11,
              fontFamily: 'DM Mono',
              color: 'var(--text-muted)',
            }}>v1.0</span>
          </div>
          <p style={{ color: 'var(--text-muted)', fontSize: 13, maxWidth: 460 }}>
            Verify email deliverability before you send. SMTP handshake, MX lookup, catch-all detection, disposable filtering, and risk scoring.
          </p>
        </div>

        {/* Tabs */}
        <div style={{ display: 'flex', gap: 4, marginBottom: 32, background: 'var(--bg2)', border: '1px solid var(--border)', borderRadius: 'var(--radius)', padding: 4, width: 'fit-content' }}>
          {TABS.map(t => (
            <button
              key={t.id}
              onClick={() => setTab(t.id)}
              style={{
                background: tab === t.id ? 'var(--bg3)' : 'transparent',
                color: tab === t.id ? 'var(--text)' : 'var(--text-muted)',
                border: tab === t.id ? '1px solid var(--border-mid)' : '1px solid transparent',
                padding: '7px 18px',
                borderRadius: 7,
                fontFamily: 'Syne',
                fontWeight: 600,
                fontSize: 13,
                cursor: 'pointer',
                transition: 'all 0.15s',
              }}
            >
              {t.label}
            </button>
          ))}
        </div>

        {/* Content */}
        <div className="animate-in" key={tab}>
          {tab === 'single' && <SingleCheck />}
          {tab === 'bulk' && <BulkVerify />}
        </div>

        {/* Footer */}
        <div style={{ marginTop: 60, paddingTop: 24, borderTop: '1px solid var(--border)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <span style={{ fontSize: 12, color: 'var(--text-dim)', fontFamily: 'DM Mono' }}>
            API: {process.env.REACT_APP_API_URL || 'http://127.0.0.1:8000'}
          </span>
          <span style={{ fontSize: 12, color: 'var(--text-dim)' }}>
            MailClean © {new Date().getFullYear()}
          </span>
        </div>
      </div>
    </div>
  );
}
